# -*- coding: utf-8 -*-
"""
=====================================================================
 01_student_system.py — 学生成绩管理系统（OOP 综合实战）
=====================================================================
【综合运用知识点】
  ✅ 面向对象（类、继承、封装、property）
  ✅ 数据容器（列表、字典）
  ✅ 文件读写 + JSON 持久化
  ✅ 异常处理
  ✅ 函数（类型注解、默认参数）
  ✅ 命令行交互（输入输出循环）

【功能】
  1. 添加学生
  2. 删除学生
  3. 修改成绩
  4. 查询学生
  5. 显示排名
  6. 统计（平均分/最高/最低）
  7. 数据自动保存/加载（JSON 文件）

【运行】python 01_student_system.py
=====================================================================
"""

import json
import os
from typing import Optional, List


# =====================================================================
# 一、数据模型层
# =====================================================================
class Student:
    """学生实体：封装学生的数据和行为"""

    def __init__(self, student_id: str, name: str, score: float = 0.0):
        self._student_id = student_id       # 学号（创建后不可改）
        self.name = name
        self.score = score

    @property
    def student_id(self) -> str:
        """学号：只读"""
        return self._student_id

    @property
    def score(self) -> float:
        return self._score

    @score.setter
    def score(self, value: float):
        """成绩：赋值时自动校验范围"""
        if not 0 <= value <= 100:
            raise ValueError("成绩必须在 0~100 之间")
        self._score = value

    def to_dict(self) -> dict:
        """转成字典（用于 JSON 序列化）"""
        return {"id": self.student_id, "name": self.name, "score": self.score}

    @classmethod
    def from_dict(cls, data: dict) -> "Student":
        """从字典创建学生（用于 JSON 反序列化）"""
        return cls(data["id"], data["name"], data["score"])

    def __repr__(self) -> str:
        return f"<Student {self.student_id} {self.name} {self.score}>"


# =====================================================================
# 二、业务逻辑层（核心服务）
# =====================================================================
class StudentManager:
    """学生管理系统：负责增删改查、统计、持久化"""

    def __init__(self, data_file: str = "students.json"):
        self.data_file = data_file
        self.students: dict[str, Student] = {}      # 用学号作键
        self.load()                                 # 启动时加载数据

    # ---------- 增 ----------
    def add_student(self, student_id: str, name: str, score: float) -> bool:
        """添加学生，学号重复返回 False"""
        if student_id in self.students:
            return False
        self.students[student_id] = Student(student_id, name, score)
        self.save()
        return True

    # ---------- 删 ----------
    def remove_student(self, student_id: str) -> bool:
        """删除学生，不存在返回 False"""
        if student_id not in self.students:
            return False
        del self.students[student_id]
        self.save()
        return True

    # ---------- 改 ----------
    def update_score(self, student_id: str, new_score: float) -> bool:
        """修改成绩（内部用 setter 校验范围）"""
        if student_id not in self.students:
            return False
        try:
            self.students[student_id].score = new_score
        except ValueError:
            return False
        self.save()
        return True

    # ---------- 查 ----------
    def get_student(self, student_id: str) -> Optional[Student]:
        """按学号查找"""
        return self.students.get(student_id)

    def search_by_name(self, keyword: str) -> List[Student]:
        """按姓名模糊搜索"""
        return [s for s in self.students.values() if keyword in s.name]

    def all_students(self) -> List[Student]:
        """所有学生"""
        return list(self.students.values())

    # ---------- 统计 ----------
    def average_score(self) -> float:
        """平均分"""
        if not self.students:
            return 0.0
        return sum(s.score for s in self.students.values()) / len(self.students)

    def highest(self) -> Optional[Student]:
        """最高分学生"""
        if not self.students:
            return None
        return max(self.students.values(), key=lambda s: s.score)

    def lowest(self) -> Optional[Student]:
        """最低分学生"""
        if not self.students:
            return None
        return min(self.students.values(), key=lambda s: s.score)

    def ranking(self) -> List[Student]:
        """按成绩从高到低排名"""
        return sorted(self.students.values(), key=lambda s: s.score, reverse=True)

    # ---------- 持久化 ----------
    def save(self):
        """保存到 JSON 文件"""
        data = [s.to_dict() for s in self.students.values()]
        with open(self.data_file, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=2)

    def load(self):
        """从 JSON 文件加载"""
        if not os.path.exists(self.data_file):
            return
        try:
            with open(self.data_file, "r", encoding="utf-8") as f:
                data = json.load(f)
            self.students = {
                item["id"]: Student.from_dict(item) for item in data
            }
        except (json.JSONDecodeError, KeyError, ValueError):
            print("数据文件损坏，已忽略（将从空数据开始）")
            self.students = {}


# =====================================================================
# 三、界面层（命令行交互）
# =====================================================================
def print_menu():
    """打印主菜单"""
    print("\n" + "=" * 40)
    print("        学生成绩管理系统")
    print("=" * 40)
    print("  1. 添加学生")
    print("  2. 删除学生")
    print("  3. 修改成绩")
    print("  4. 查询学生")
    print("  5. 显示排名")
    print("  6. 统计信息")
    print("  7. 显示所有学生")
    print("  0. 退出")
    print("=" * 40)


def input_score(prompt: str) -> float:
    """安全输入成绩（带校验和异常处理）"""
    while True:
        try:
            score = float(input(prompt))
            if not 0 <= score <= 100:
                print("成绩必须在 0~100 之间，请重新输入")
                continue
            return score
        except ValueError:
            print("请输入数字")


def main():
    """主程序入口"""
    manager = StudentManager()

    while True:
        print_menu()
        choice = input("请选择操作：").strip()

        # ---------- 添加 ----------
        if choice == "1":
            student_id = input("学号：").strip()
            name = input("姓名：").strip()
            if not student_id or not name:
                print("学号和姓名不能为空")
                continue
            score = input_score("成绩：")
            if manager.add_student(student_id, name, score):
                print(f"✅ 添加成功：{name}（学号 {student_id}）")
            else:
                print(f"❌ 学号 {student_id} 已存在")

        # ---------- 删除 ----------
        elif choice == "2":
            student_id = input("要删除的学号：").strip()
            if manager.remove_student(student_id):
                print(f"✅ 已删除学号 {student_id}")
            else:
                print(f"❌ 学号 {student_id} 不存在")

        # ---------- 修改 ----------
        elif choice == "3":
            student_id = input("要修改的学号：").strip()
            student = manager.get_student(student_id)
            if not student:
                print(f"❌ 学号 {student_id} 不存在")
                continue
            print(f"当前成绩：{student.name} = {student.score}")
            new_score = input_score("新的成绩：")
            if manager.update_score(student_id, new_score):
                print(f"✅ {student.name} 的成绩已更新为 {new_score}")
            else:
                print("❌ 更新失败")

        # ---------- 查询 ----------
        elif choice == "4":
            keyword = input("输入学号或姓名关键字：").strip()
            # 先按学号精确查
            if student := manager.get_student(keyword):
                print(f"  学号 {student.student_id}：{student.name}，{student.score} 分")
            else:
                # 再按姓名模糊查
                results = manager.search_by_name(keyword)
                if results:
                    for s in results:
                        print(f"  {s.student_id}  {s.name}  {s.score} 分")
                else:
                    print("❌ 未找到匹配的学生")

        # ---------- 排名 ----------
        elif choice == "5":
            ranking = manager.ranking()
            if not ranking:
                print("暂无学生数据")
                continue
            print("\n🏆 成绩排名：")
            for i, s in enumerate(ranking, start=1):
                medal = "🥇" if i == 1 else ("🥈" if i == 2 else ("🥉" if i == 3 else "  "))
                print(f"  {medal} 第{i}名  {s.name}（{s.student_id}） {s.score} 分")

        # ---------- 统计 ----------
        elif choice == "6":
            if not manager.students:
                print("暂无学生数据")
                continue
            highest = manager.highest()
            lowest = manager.lowest()
            print(f"  学生人数：{len(manager.students)}")
            print(f"  平均分：{manager.average_score():.1f}")
            print(f"  最高分：{highest.name} {highest.score} 分")
            print(f"  最低分：{lowest.name} {lowest.score} 分")

        # ---------- 全部 ----------
        elif choice == "7":
            if not manager.students:
                print("暂无学生数据")
                continue
            print(f"\n共 {len(manager.students)} 名学生：")
            for s in manager.all_students():
                print(f"  {s.student_id}  {s.name}  {s.score} 分")

        # ---------- 退出 ----------
        elif choice == "0":
            print("感谢使用，再见！")
            break

        else:
            print("无效选择，请输入 0~7")


if __name__ == "__main__":
    main()

