# -*- coding: utf-8 -*-
"""
=====================================================================
 10_web_app/
 03_todo_web_app.py — Flask 待办事项 Web 应用（综合实战）
=====================================================================
【综合运用知识点】
  ✅ Flask 路由与模板（Jinja2）
  ✅ 表单提交（POST）
  ✅ 重定向与 flash 消息（PRG 模式）
  ✅ JSON 数据持久化
  ✅ 面向对象（Todo 模型）
  ✅ 列表增删改查

【功能】
  1. 添加任务（可设优先级）
  2. 标记完成 / 取消完成
  3. 删除任务
  4. 编辑任务标题
  5. 数据持久化（JSON 文件）

【运行】python 03_todo_web_app.py
  然后浏览器打开 http://127.0.0.1:5002
=====================================================================
"""

import json
import os
import pathlib
from dataclasses import dataclass, field, asdict

from flask import Flask, render_template, request, redirect, url_for, flash

BASE = pathlib.Path(__file__).parent
DATA_FILE = BASE / "todos.json"
TEMPLATES = BASE / "templates"
TEMPLATES.mkdir(exist_ok=True)

# ---------------------------------------------------------------------
