 */
const { C, p, code, h1, h2, h3, bullet, callout, makeTable, tableSpacer } = require("./helpers");

// ============================================================
// 第一部分：封面内容
// ============================================================
function coverSection() {
  return [
    // 顶部留白
    new (require("./helpers")).Paragraph({ spacing: { before: 2400 }, children: [] }),
    p("Python 学习代码合集", {
      alignment: require("./helpers").AlignmentType.CENTER,
      after: 100,
    }),
    new (require("./helpers")).Paragraph({
      alignment: require("./helpers").AlignmentType.CENTER,
      children: [
        new (require("./helpers")).TextRun({
          text: "Python 学习代码合集",
          font: "Microsoft YaHei",
          size: 64,
          bold: true,
          color: C.primary,
        }),
      ],
      spacing: { after: 120 },
    }),
    new (require("./helpers")).Paragraph({
      alignment: require("./helpers").AlignmentType.CENTER,
      children: [
        new (require("./helpers")).TextRun({
          text: "指导手册",
          font: "Microsoft YaHei",
          size: 44,
          bold: true,
          color: C.dark,
        }),
      ],
      spacing: { after: 300 },
    }),
    p("基于 python-tutorial 目录下 51 个示例文件的系统学习指南", {
      alignment: require("./helpers").AlignmentType.CENTER,
      after: 500,
    }),
    p("涵盖：基础语法 · 函数与模块 · 面向对象 · 进阶特性 · 并发编程", {
      alignment: require("./helpers").AlignmentType.CENTER,
      after: 80,
    }),
    p("数据分析 · 网络爬虫 · Web 开发 · 工程化实践", {
      alignment: require("./helpers").AlignmentType.CENTER,
      after: 300,
    }),
    p("配套代码目录：D:\\python\\python-tutorial", {
      alignment: require("./helpers").AlignmentType.CENTER,
      after: 60,
    }),
    p("版本：v1.0 · 2026年8月", {
      alignment: require("./helpers").AlignmentType.CENTER,
    }),
  ];
}

// ============================================================
// 第二部分：前言 / 使用说明
// ============================================================
function prefaceSection() {
  return [
    h1("前言 · 如何使用本手册与配套代码"),
    p("本手册是《Python 学习代码合集》的配套指导文档。代码合集位于 D:\\python\\python-tutorial 目录，共 10 个学习章节、51 个 Python 示例文件、1 个 Markdown 笔记文档。每个知识点对应一个独立文件，文件内注释详细、可直接运行。"),
    h2("一、环境准备"),
    bullet([{ text: "安装 Python 3.8 及以上版本（推荐 3.10+，本教程在 3.14 上验证通过）" }]),
    bullet([{ text: "安装编辑器：VS Code（推荐）或 PyCharm" }]),
    bullet([{ text: "进阶章节（08~10）需要安装第三方库：" }]),
    code("pip install numpy pandas matplotlib requests beautifulsoup4 lxml flask"),
    bullet([{ text: "建议使用虚拟环境安装依赖，避免各项目冲突（详见 06_engineering 章节）" }]),
    h2("二、运行示例代码"),
    code("cd D:\\python\\python-tutorial\npython 01_basics\\01_hello_world.py"),
    bullet([{ text: "Windows 下若 python 不可用，可尝试 py 命令" }]),
    bullet([{ text: "部分示例（如 02_variables、05_strings）运行到最后会调用 input() 等待输入，直接回车即可完成演示" }]),
    bullet([{ text: "10_web_app 章节需要启动 Web 服务器后，在浏览器中访问 http://127.0.0.1:5000 等地址" }]),
    h2("三、学习方法建议"),
    bullet([{ text: "先读文件顶部注释了解本节知识点，再运行代码观察输出" }]),
    bullet([{ text: "动手修改示例中的数字、字符串、条件，看结果如何变化" }]),
    bullet([{ text: "每个章节末尾通常有『动手区』练习，建议先自己尝试再对照参考答案" }]),
    bullet([{ text: "报错不可怕：04_advanced/01_exceptions.py 会教你读懂各类报错" }]),
    bullet([{ text: "按 01 → 07 顺序学习基础，08~10 为进阶方向，可任选" }]),
    callout("学习路线总览", "第1步 基础语法 → 第2步 函数与模块 → 第3步 面向对象 → 第4步 进阶特性 → 第5步 并发编程 → 第6步 工程化 → 第7步 综合实战 → 第8步 数据分析 / 爬虫 / Web（三选一或全学）", C.lightBg, C.primary),
  ];
