      { name: "05_strings.py", desc: "字符串详解", points: ["索引与切片（含负索引、步长）", "常用方法：upper/split/join/replace", "字符串判断方法 isdigit 等", "三种格式化：% / format / f-string", "字符编码 ord/chr"] },
      { name: "06_operators.py", desc: "运算符大全", points: ["算术、比较、赋值、逻辑运算符", "短路求值 and/or", "in 成员运算符、is 身份运算符", "位运算符与优先级"] },
      { name: "07_control_flow.py", desc: "流程控制 if/elif/else", points: ["单分支、双分支、多分支", "嵌套 if 与条件合并", "truthy/falsy 简化判断", "三目运算符", "match-case 语句（3.10+）"] },
      { name: "08_loops.py", desc: "循环 for / while", points: ["for 遍历字符串/列表/字典", "range() 三种参数", "enumerate / zip 配套遍历", "break / continue / else", "while 循环与死循环预防", "嵌套循环与乘法表"] },
      { name: "09_lists.py", desc: "列表 List", points: ["索引切片与切片赋值", "增删改：append/insert/remove/pop", "sort / sorted / reverse", "浅拷贝 vs 深拷贝（重点）", "二维列表与常见坑"] },
      { name: "10_tuples.py", desc: "元组 Tuple", points: ["元组不可变性", "单元素元组写法", "元组解包（星号解包）", "元组作字典键", "namedtuple 命名元组"] },
      { name: "11_dicts.py", desc: "字典 Dict", points: ["键值对增删改查", "get / setdefault / update", "遍历字典多种方式", "字典解包 ** 与合并", "嵌套字典结构"] },
      { name: "12_sets.py", desc: "集合 Set", points: ["集合无序唯一特性", "交集/并集/差集/对称差集", "去重经典应用", "frozenset 不可变集合"] },
      { name: "13_comprehensions.py", desc: "推导式", points: ["列表推导式与条件过滤", "嵌套循环推导式", "字典推导式、集合推导式", "生成器表达式（省内存）", "可读性建议"] },
    ],
  },
  {
