// ============================================================
// 渲染章节内容
// ============================================================
function renderChapter(ch) {
  const { p, code, h1, h2, h3, bullet, callout, makeTable, tableSpacer, C } = require("./helpers");
  const paragraphs = [
    h1(`${ch.num}　${ch.title}`),
    p(ch.intro),
  ];

  const rows = ch.files.map((f) => [
    [{ text: f.name, bold: true, color: C.primary }],
    f.desc,
    f.points.join("；"),
  ]);
  const widths = [3600, 2200, 4700];
  paragraphs.push(
    new (require("./helpers")).Paragraph({
      heading: require("./helpers").HeadingLevel.HEADING_2,
      spacing: { before: 200, after: 120 },
      children: [new (require("./helpers")).TextRun({ text: "章节文件总览", font: "Microsoft YaHei", size: 28, bold: true, color: require("./helpers").C.dark })],
    }),
    makeTable(["文件名", "说明", "覆盖知识点"], rows, widths),
    tableSpacer()
  );

  // 每个文件的详细指导
  ch.files.forEach((f) => {
    paragraphs.push(h3(`${f.name}　—　${f.desc}`));
    paragraphs.push(p(`运行方式：`, {}));
    paragraphs.push(code(`python ${ch.num === "01" ? "01_basics" : ch.num === "02" ? "02_functions_modules" : ch.num === "03" ? "03_oop" : ch.num === "04" ? "04_advanced" : ch.num === "05" ? "05_concurrency" : ch.num === "06" ? "06_engineering" : ch.num === "07" ? "07_projects" : ch.num === "08" ? "08_data_analysis" : ch.num === "09" ? "09_web_scraping" : "10_web_app"}\\${f.name}`));
    paragraphs.push(p("学习要点："));
    f.points.forEach((pt) => paragraphs.push(bullet(pt)));
    paragraphs.push(new (require("./helpers")).Paragraph({ spacing: { after: 100 }, children: [] }));
  });

  return paragraphs;
}

// ============================================================
// 学习路线与附录
// ============================================================
function roadmapSection() {
  return [
    h1("学习路线与进阶建议"),
    h2("建议的学习顺序"),
    makeTable(
      ["阶段", "内容", "预计用时"],
      [
        ["第 1 步", "01_basics 基础语法", "1~2 周"],
        ["第 2 步", "02_functions_modules 函数与模块", "3~5 天"],
        ["第 3 步", "03_oop 面向对象", "3~5 天"],
        ["第 4 步", "04_advanced 进阶特性", "1 周"],
        ["第 5 步", "05_concurrency 并发与异步", "3~5 天（了解即可）"],
        ["第 6 步", "06_engineering 工程化", "边学边用"],
        ["第 7 步", "07_projects 综合实战", "1 周（重要！）"],
        ["第 8 步", "08/09/10 进阶方向", "按兴趣任选"],
      ],
      [1200, 4000, 1300]
    ),
    tableSpacer(),
    h2("三个进阶方向如何选择"),
    bullet([{ text: "对数据处理、可视化感兴趣 → 08 数据分析（NumPy / Pandas / Matplotlib）" }]),
    bullet([{ text: "对采集数据、自动化感兴趣 → 09 网络爬虫（requests / BeautifulSoup）" }]),
    bullet([{ text: "对开发网站、API 感兴趣 → 10 Web 开发（Flask）" }]),
    callout("建议", "先完整学完 01~07 打好基础，08~10 可按兴趣深入学习。每个方向都是进入对应职业领域的起点。", C.greenBg, C.teal),
    h2("学完后的能力清单"),
    bullet([{ text: "写出规范、可读、带注释的 Python 代码" }]),
    bullet([{ text: "理解并运用面向对象编程思想（封装、继承、多态）" }]),
    bullet([{ text: "掌握文件、JSON、CSV、正则、日期时间等常用工具" }]),
    bullet([{ text: "会用类型注解、单元测试、日志记录" }]),
    bullet([{ text: "理解多线程、多进程、异步的区别与取舍" }]),
    bullet([{ text: "能独立完成小型命令行工具与数据处理任务" }]),
    bullet([{ text: "具备进一步学习数据分析 / 爬虫 / Web 开发的基础" }]),
  ];
}

function appendixSection() {
  return [
    h1("附录：常见问题与命令速查"),
    h2("一、运行相关"),
    makeTable(
      ["问题", "解决方法"],
      [
        ["python 命令找不到", "重装时勾选 Add to PATH，或使用 py 命令"],
        ["中文输出乱码", "终端执行 chcp 65001 切换 UTF-8，或在 VS Code 中运行"],
        ["端口被占用", "Flask 的 app.run 改 port 参数"],
        ["第三方库未安装", "pip install 对应库（见各章节顶部注释）"],
      ],
      [2600, 5900]
    ),
    tableSpacer(),
    h2("二、高频命令速查"),
    code("python 文件名.py            # 运行脚本\npython -m py_compile 文件.py   # 仅检查语法\npython -m venv venv            # 创建虚拟环境\npip install -r requirements.txt # 安装依赖\npytest 文件名.py               # 运行测试\nmypy 文件名.py                 # 类型检查"),
    h2("三、代码风格建议"),
    bullet([{ text: "缩进统一 4 空格，不要混用 Tab" }]),
    bullet([{ text: "变量命名用 snake_case，类名用 PascalCase" }]),
    bullet([{ text: "每行建议不超过 79 字符（PEP 8）" }]),
    bullet([{ text: "重要函数写 docstring，说明参数与返回值" }]),
    bullet([{ text: "多写注释说明『为什么』，而非『是什么』" }]),
    h2("四、继续学习的方向"),
    bullet([{ text: "Web 框架进阶：Django、FastAPI" }]),
    bullet([{ text: "数据科学：机器学习（scikit-learn）、深度学习（PyTorch）" }]),
    bullet([{ text: "自动化：Selenium 浏览器自动化、Playwright" }]),
    bullet([{ text: "数据库：SQLite（内置）、SQLAlchemy ORM" }]),
    bullet([{ text: "项目部署：Docker、Gunicorn、Nginx" }]),
  ];
}

module.exports = { coverSection, prefaceSection, renderChapter, roadmapSection, appendixSection, chapters };

