  red: "C0392B",        // 红色
  gray: "666666",
  lightBg: "EAF1FB",    // 浅蓝底
  greenBg: "E8F5EE",
  orangeBg: "FDF0E3",
  headerBg: "1F6FEB",
  headerText: "FFFFFF",
  rowAlt: "F4F8FE",
};

const FONT = "Microsoft YaHei";

// 十六进制颜色 → 可用字符串
function shade(hex) {
  return { fill: hex };
}

// 通用正文段落
function p(text, opts = {}) {
  const runs = Array.isArray(text) ? text : [{ text }];
  return new Paragraph({
    children: runs.map(
      (r) =>
        new TextRun({
          text: r.text,
          bold: r.bold || false,
          italics: r.italic || false,
          color: r.color || "333333",
          size: r.size || 22,
          font: FONT,
          highlight: r.highlight,
        })
    ),
    spacing: { after: opts.after ?? 120, before: opts.before ?? 0 },
    indent: opts.indent,
    alignment: opts.alignment,
  });
}

// 代码块样式段落（等宽字体 + 浅色底纹用边框文本）
function code(text) {
  return new Paragraph({
    children: [
      new TextRun({
        text,
        font: "Consolas",
        size: 20,
        color: "C0392B",
        shading: shade("F7F7F7"),
      }),
    ],
    spacing: { after: 60, before: 60 },
    indent: { left: 240 },
    border: {
      left: { style: BorderStyle.SINGLE, size: 12, color: "DDDDDD" },
    },
  });
}

// 标题段落（用于章节标题）
function h1(text, color = C.primary) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    spacing: { before: 360, after: 200 },
    children: [
      new TextRun({ text, font: FONT, size: 34, bold: true, color }),
    ],
  });
}

function h2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    spacing: { before: 280, after: 160 },
    children: [
      new TextRun({ text, font: FONT, size: 28, bold: true, color: C.dark }),
    ],
  });
}

function h3(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_3,
    spacing: { before: 220, after: 120 },
    children: [
      new TextRun({ text, font: FONT, size: 24, bold: true, color: C.primary }),
    ],
  });
}

// 项目符号
function bullet(text, level = 0) {
  const runs = Array.isArray(text) ? text : [{ text }];
  return new Paragraph({
    children: runs.map(
      (r) =>
        new TextRun({
          text: r.text,
          bold: r.bold || false,
          color: r.color || "333333",
          size: r.size || 22,
          font: FONT,
        })
    ),
    bullet: { level },
    spacing: { after: 80 },
  });
}

// 强调框段落（带底纹）
function callout(title, text, bgColor, barColor) {
  return new Paragraph({
    children: [
      new TextRun({
        text: title ? "★ " + title + "\n" : "",
        font: FONT,
        size: 22,
        bold: true,
        color: barColor,
      }),
      new TextRun({ text, font: FONT, size: 22, color: "333333" }),
    ],
    shading: shade(bgColor),
    spacing: { before: 120, after: 120 },
    border: {
      left: { style: BorderStyle.SINGLE, size: 24, color: barColor },
    },
    indent: { left: 240 },
  });
}

// ============================================================
// 表格工具
// ============================================================
function makeCell(text, { width, bold = false, fill, color, align } = {}) {
  const runs = (Array.isArray(text) ? text : [text]).map(
    (t, i) =>
      new TextRun({
        text: typeof t === "string" ? t : t.text,
        bold: typeof t === "string" ? (i === 0 && bold) : (t.bold ?? false),
        color: typeof t === "string" ? (color || "333333") : (t.color || "333333"),
        size: 20,
        font: FONT,
      })
  );
  return new TableCell({
    width: { size: width, type: WidthType.DXA },
    shading: fill ? { fill } : undefined,
    children: [
      new Paragraph({
        children: runs,
        alignment: align || AlignmentType.LEFT,
        spacing: { after: 40, before: 40 },
      }),
    ],
    verticalAlign: "center",
  });
}

function makeTable(headers, rows, widths) {
  const headerCells = headers.map((h, i) =>
    makeCell(h, { width: widths[i], bold: true, fill: C.headerBg, color: C.headerText })
  );
  const bodyRows = rows.map((r, ri) => {
    const cells = r.map((cell, ci) =>
      makeCell(cell, {
        width: widths[ci],
        fill: ri % 2 === 1 ? C.rowAlt : undefined,
      })
    );
    return new TableRow({ children: cells });
  });
  return new Table({
    width: { size: widths.reduce((a, b) => a + b, 0), type: WidthType.DXA },
    columnWidths: widths,
    rows: [new TableRow({ children: headerCells }), ...bodyRows],
  });
}

// 表格下方留白
function tableSpacer() {
  return new Paragraph({ spacing: { after: 160 }, children: [] });
}

// ============================================================
// 页面设置（A4，页边距适中）
// ============================================================
const PAGE_W = 11906; // A4 宽 DXA (210mm)
const PAGE_H = 16838; // A4 高 DXA (297mm)
const MARGIN = 1440;  // 2.54cm

module.exports = {
  C, FONT, p, code, h1, h2, h3, bullet, callout,
  makeTable, tableSpacer, makeCell,
  PAGE_W, PAGE_H, MARGIN, Paragraph, TextRun, AlignmentType,
  Document, Packer, TableOfContents, PageNumber, Footer, PageNumberFormat,
  LevelFormat, TabStopType, HeadingLevel, path, fs,
};

