 * 运行：node generate_manual.js
 */
const {
  Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType,
  TableOfContents, PageNumber, Footer, PageNumberFormat,
  LevelFormat, TabStopType, Table, TableRow, TableCell, WidthType,
} = require("C:/Users/TOT/AppData/Local/Claude-3p/local-agent-mode-sessions/skills-plugin/00000000-0000-4000-8000-000000000001/007611b7-3bf0-4436-8cca-eff9e9fda589/skills/docx/node_modules/docx");
const { coverSection, prefaceSection, renderChapter, roadmapSection, appendixSection, chapters } = require("./content");
const { PAGE_W, PAGE_H, MARGIN, C, FONT } = require("./helpers");
const path = require("path");

// ============================================================
// 组装文档内容
// ============================================================
function buildBody() {
  const body = [];

  // 封面
  body.push(...coverSection());

  // 目录（Word 打开后按 F9 更新域）
  body.push(
    new Paragraph({
      heading: HeadingLevel.HEADING_1,
      children: [new TextRun({ text: "目录", font: FONT, size: 34, bold: true, color: C.primary })],
      spacing: { before: 1200, after: 200 },
    }),
    new TableOfContents("目录", { hyperlink: true, headingStyleRange: "1-3" })
  );

  // 前言
  body.push(...prefaceSection());

  // 各章节
  chapters.forEach((ch) => body.push(...renderChapter(ch)));

  // 学习路线与附录
  body.push(...roadmapSection());
  body.push(...appendixSection());

  return body;
}

// ============================================================
// 文档设置：A4，页脚页码，页边距
// ============================================================
function buildDocument() {
  return new Document({
    styles: {
      paragraphStyles: [
        {
          id: "Heading1",
          name: "Heading 1",
          basedOn: "Normal",
          next: "Normal",
          quickFormat: true,
          run: { font: FONT, size: 34, bold: true, color: C.primary },
          paragraph: { spacing: { before: 360, after: 200 }, outlineLevel: 0 },
        },
        {
          id: "Heading2",
          name: "Heading 2",
          basedOn: "Normal",
          next: "Normal",
          quickFormat: true,
          run: { font: FONT, size: 28, bold: true, color: C.dark },
          paragraph: { spacing: { before: 280, after: 160 }, outlineLevel: 1 },
        },
        {
          id: "Heading3",
          name: "Heading 3",
          basedOn: "Normal",
          next: "Normal",
          quickFormat: true,
          run: { font: FONT, size: 24, bold: true, color: C.primary },
          paragraph: { spacing: { before: 220, after: 120 }, outlineLevel: 2 },
        },
      ],
    },
    numbering: {
      config: [
        {
          reference: "bullets",
          levels: [
            { level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 480, hanging: 260 } } } },
            { level: 1, format: LevelFormat.BULLET, text: "\u25E6", alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 960, hanging: 260 } } } },
          ],
        },
      ],
    },
    features: {
      updateFields: true, // 打开文档时提示更新目录
    },
    footers: {
      default: new Footer({
        children: [
          new Paragraph({
            alignment: AlignmentType.CENTER,
            children: [
              new TextRun({ text: "Python 学习代码合集 · 指导手册  |  第 ", font: FONT, size: 18, color: C.gray }),
              new TextRun({ children: [PageNumber.CURRENT], font: FONT, size: 18, color: C.gray }),
              new TextRun({ text: " 页", font: FONT, size: 18, color: C.gray }),
            ],
          }),
        ],
      }),
    },
    sections: [
      {
        properties: {
          page: {
            size: { width: PAGE_W, height: PAGE_H },
            margin: { top: MARGIN, bottom: MARGIN, left: 1300, right: 1300 },
          },
        },
        children: buildBody(),
      },
    ],
  });
}

// ============================================================
// 输出
// ============================================================
async function main() {
  const doc = buildDocument();
  const outPath = path.join(__dirname, "Python学习代码合集指导手册.docx");
  const buffer = await Packer.toBuffer(doc);
  require("fs").writeFileSync(outPath, buffer);
  console.log("已生成:", outPath, `(${(buffer.length / 1024).toFixed(1)} KB)`);
}

main().catch((e) => {
  console.error("生成失败:", e);
  process.exit(1);
});

